use matrix::Matrix;

#[test]
fn test_new_is_zeros() {
    let m = Matrix::new(2, 3);
    assert_eq!(m.get(0, 0), 0.0);
    assert_eq!(m.get(1, 2), 0.0);
    assert_eq!(m.rows(), 2);
    assert_eq!(m.cols(), 3);
}

#[test]
fn test_set_and_get() {
    let mut m = Matrix::new(2, 2);
    m.set(0, 1, 5.0);
    m.set(1, 0, 3.0);
    assert_eq!(m.get(0, 1), 5.0);
    assert_eq!(m.get(1, 0), 3.0);
    assert_eq!(m.get(0, 0), 0.0);
}

#[test]
fn test_transpose() {
    let mut m = Matrix::new(2, 3);
    m.set(0, 1, 7.0);
    m.set(1, 2, 4.0);
    let t = m.transpose();
    assert_eq!(t.rows(), 3);
    assert_eq!(t.cols(), 2);
    assert_eq!(t.get(1, 0), 7.0); // m[0][1] -> t[1][0]
    assert_eq!(t.get(2, 1), 4.0); // m[1][2] -> t[2][1]
}

#[test]
fn test_add_matching_dims() {
    let mut a = Matrix::new(2, 2);
    a.set(0, 0, 1.0);
    a.set(1, 1, 2.0);
    let mut b = Matrix::new(2, 2);
    b.set(0, 0, 3.0);
    b.set(1, 1, 4.0);
    let c = a.add(&b).expect("dims match");
    assert_eq!(c.get(0, 0), 4.0);
    assert_eq!(c.get(1, 1), 6.0);
    assert_eq!(c.get(0, 1), 0.0);
}

#[test]
fn test_add_mismatched_dims_returns_none() {
    let a = Matrix::new(2, 3);
    let b = Matrix::new(3, 2);
    assert!(a.add(&b).is_none());
}

#[test]
fn test_transpose_identity() {
    let mut m = Matrix::new(3, 3);
    m.set(0, 1, 9.0);
    m.set(2, 0, 5.0);
    let tt = m.transpose().transpose();
    assert_eq!(tt.get(0, 1), 9.0);
    assert_eq!(tt.get(2, 0), 5.0);
    assert_eq!(tt.rows(), 3);
    assert_eq!(tt.cols(), 3);
}
